// Pull fcp PRs with the timeline facts the delivery metrics need.
import { graphql } from "./gh.js"; // fetch POST https://api.github.com/graphql with a read-only App token
import type { PrSearch } from "./types.js"; // the shape of this query's result

const QUERY = `
query($q: String!, $after: String) {
  search(query: $q, type: ISSUE, first: 50, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes { ... on PullRequest {
      number createdAt mergedAt bodyText author { login }
      commits(first: 100) { nodes { commit { authoredDate message } } }
      timelineItems(itemTypes: [READY_FOR_REVIEW_EVENT, PULL_REQUEST_REVIEW], first: 50) {
        nodes { __typename
          ... on ReadyForReviewEvent { createdAt }
          ... on PullRequestReview { createdAt state author { login __typename } } } }
    } }
  }
}`;

/** One week per query (GitHub search stops at 1000 results). Run again with field = "merged". */
export async function* pullRequests(repo: string, weekStart: string, weekEnd: string, field: "created" | "merged" = "created") {
  const q = `repo:${repo} is:pr ${field}:${weekStart}..${weekEnd}`;
  let after: string | null = null;
  do {
    const { search }: PrSearch = await graphql(QUERY, { q, after });
    for (const { commits, timelineItems, ...pr } of search.nodes) {
      const done = commits.nodes.map((n) => n.commit);
      const firstCommitAt = done.map((c) => c.authoredDate).sort()[0] ?? pr.createdAt; // ISO strings sort by time
      const aiTrailer = pr.bodyText.includes("Generated with Claude Code") || done.some((c) => c.message.includes("Co-Authored-By: Claude"));
      yield { ...pr, firstCommitAt, aiTrailer, timeline: timelineItems.nodes };
    }
    after = search.pageInfo.hasNextPage ? search.pageInfo.endCursor : null;
  } while (after);
}

// Hours fcp main stays red, from the required unit-test jobs only (I&T flakiness is G7's problem).
import { rest, restPages } from "./gh.js"; // small fetch helpers with the read-only App token; restPages follows Link: next
import type { Job, WorkflowRun } from "./types.js";
const REQUIRED: Record<string, string[]> = { // workflow file -> job names (the second one is the name before G0's rename)
  "cloud-ci.yml": ["Cloud Unit Tests", "Unit Tests"],
  "client-ci.yml": ["Client Unit Tests", "Unit Tests"],
  "frontend-ci.yaml": ["Frontend Unit Tests", "Unit Tests"],
};
export type Result = { workflow: string; at: Date; ok: boolean };
export async function* mainResults(repo: string, since: string): AsyncGenerator<Result> {
  for (const [workflow, names] of Object.entries(REQUIRED)) {
    const query = { branch: "main", status: "completed", created: `>=${since}` };
    for await (const run of restPages<WorkflowRun>(`/repos/${repo}/actions/workflows/${workflow}/runs`, query)) {
      const { jobs } = await rest<{ jobs: Job[] }>(`/repos/${repo}/actions/runs/${run.id}/jobs`);
      const job = jobs.find((j) => names.includes(j.name));
      if (job?.completed_at && (job.conclusion === "success" || job.conclusion === "failure")) {
        yield { workflow, at: new Date(job.completed_at), ok: job.conclusion === "success" };
      }
    }
  }
}

/** main is red while any required job's latest result is a failure; overlaps count once. */
export function redHours(results: Result[]): number {
  const state = new Map<string, boolean>();
  let redSince: Date | undefined, total = 0;
  for (const { workflow, at, ok } of results.toSorted((a, b) => a.at.getTime() - b.at.getTime())) {
    state.set(workflow, ok);
    const redNow = [...state.values()].includes(false);
    if (redNow && !redSince) redSince = at;
    else if (!redNow && redSince) { total += (at.getTime() - redSince.getTime()) / 3_600_000; redSince = undefined; }
  }
  return total;
}

// Weekly, team-level delivery metrics. Nothing here is ever written per person.
import { days, hours, median, quantile } from "./stats.js"; // ISO timestamps in, numbers out; quantile as Python's statistics
import type { Fix, MergedPr, Point, PullRequest } from "./types.js";

/** Ready for review (or opened, if never a draft) to the first review by another person. */
export function reviewWaitHours(pr: PullRequest): number | undefined {
  const ready = pr.timeline.find((e) => e.__typename === "ReadyForReviewEvent")?.createdAt ?? pr.createdAt;
  const first = pr.timeline.find((e) => e.__typename === "PullRequestReview"
    && e.author?.__typename === "User" && e.author.login !== pr.author.login)?.createdAt;
  return first ? hours(ready, first) : undefined;
}

export const leadTimeHours = (pr: PullRequest) => (pr.mergedAt ? hours(pr.firstCommitAt, pr.mergedAt) : undefined);

/** A revert, hotfix or Bug fix within 14 days on the same lines (G2's miner does the blame). */
export const changeFailed = (pr: MergedPr, fixes: Fix[]) =>
  fixes.some((f) => f.introducedBy === pr.number && days(pr.mergedAt, f.mergedAt) <= 14);

export function* weeklyPoints(prs: PullRequest[], fixes: Fix[], teamOf: (pr: PullRequest) => string, weekTs: number): Generator<Point> {
  const byTeam = new Map<string, PullRequest[]>();
  for (const pr of prs) { // agent PRs count for the requester's team; teams under 3 people map to "other"
    byTeam.set(teamOf(pr), [...(byTeam.get(teamOf(pr)) ?? []), pr]);
  }
  for (const [team, items] of byTeam) {
    const waits = items.map(reviewWaitHours).filter((w) => w !== undefined);
    if (waits.length >= 2) {
      yield ["delivery_review_wait_hours", { team, q: "p50" }, median(waits), weekTs];
      yield ["delivery_review_wait_hours", { team, q: "p85" }, quantile(waits, 0.85), weekTs];
    }
    const merged = items.filter((p): p is MergedPr => p.mergedAt !== null);
    yield ["delivery_merged_prs", { team }, merged.length, weekTs];
    yield ["delivery_failed_changes", { team }, merged.filter((p) => changeFailed(p, fixes)).length, weekTs];
  }
}

